    let temp = head;
    let count = 0;
    while (temp !== null && count < k) {
        temp = temp.next;
        count++;
    }

    let groupHead = reverseKNodes(head, k);

    // Recursion for the next group
    head.next = reverseKGroup(temp, k);

    return groupHead;
